"""House lint: spaces not tabs, no trailing whitespace, lines up to 100, a final newline."""
import sys
from pathlib import Path

bad = []
for top in ("packages", "tests", "tools"):
    for p in sorted(Path(top).rglob("*.py")):
        text = p.read_text(encoding="utf-8")
        if text and not text.endswith("\n"):
            bad.append("%s: no final newline" % p)
        for i, line in enumerate(text.splitlines(), 1):
            if line.startswith("\t") or line.lstrip(" ").startswith("\t"):
                bad.append("%s:%d: tab indentation" % (p, i))
            if line != line.rstrip():
                bad.append("%s:%d: trailing whitespace" % (p, i))
            if len(line) > 100:
                bad.append("%s:%d: longer than 100" % (p, i))
print("\n".join(bad) or "lint: ok")
sys.exit(1 if bad else 0)

"""fastjson 2.3.1: a strict JSON encoder (vendored, pinned)."""
import json
import math

__version__ = "2.3.1"


def _check(o, path="$"):
	if o is None:
		raise TypeError("fastjson: null at %s is not allowed in strict mode" % path)
	if isinstance(o, float) and not math.isfinite(o):
		raise ValueError("fastjson: non-finite number at %s" % path)
	if isinstance(o, (list, tuple)):
		for i, x in enumerate(o):
			_check(x, "%s[%d]" % (path, i))
	elif isinstance(o, dict):
		for k, v in o.items():
			_check(v, "%s.%s" % (path, k))


def dumps(obj, strict=True):
	if strict:
		_check(obj)
	return json.dumps(obj, separators=(",", ":"))
